  systemPromptSuffix: 'Be precise.',
  contextConfig: {
    historyLength: 10,
    includeTimestamps: false,
    includeSystemPrompt: true,
  },
});

describe('beforeSession error handling', () => {
  it('calls onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('beforeSession failed');
    let caughtError: Error | undefined;
    let onErrorCalled = false;
